    "001d1c16": {"text":"Une voix porte plus de quarante querelles.","hash":"h1-1516600e"},
    "002e9d5f": {"text":"Fille","hash":"h1-9d4577b5"},
    "004517b3": {"text":"Culturel","hash":"h1-e7cf97d9"},
    "004a2f0a": {"text":"Juré de paix publique avec un rival.","hash":"h1-b9bcb1e6"},
    "004c5e61": {"text":"Rival","hash":"h1-561c3eeb"},
    "00c81938": {"text":"Prêchez aux villageois.","hash":"h1-bf536903"},
